with base as (select *, round(quantity, 1) as quantity_rounded, case when quantity >= 193 then 'High' when quantity >= 48 then 'Medium' else 'Low' end as quantity_level from inventory where last_restock >= '2024-04-14') select date_trunc('month', last_restock) as activity_month, count(distinct id) as distinct_ids, count(*) as event_count, count(distinct product_id) as distinct_product_ids, round(avg(quantity), 2) as avg_quantity from base group by rollup (date_trunc('month', last_restock)) having distinct_ids > 1;
